(function(){
const $=s=>document.querySelector(s), esc=Pema.esc, icon=PemaUI.icon;
let screen='home', identity='P001', toastTimer, draftMessage='', draftPhoto=null, draftConsent=false;
try { const storedIdentity=localStorage.getItem('pema-patient-identity'); if(storedIdentity && Pema.state.patients.some(q=>q.id===storedIdentity)) identity=storedIdentity; } catch (_) {}
try { localStorage.setItem('pema-patient-identity',identity); } catch (_) {}
let historyLimit=3;
const nav=[['home','house','Trang chủ'],['appointments','calendar-days','Lịch hẹn'],['journey','route','Hành trình'],['messages','message-circle','Tin nhắn'],['profile','user-round','Hồ sơ']];
function p(){return Pema.patient(identity)}
function stateSnapshot(){return JSON.stringify(Pema.state)}
function restoreState(snapshot){try{const current=Pema.state, restored=JSON.parse(snapshot);Object.keys(current).forEach(k=>delete current[k]);Object.assign(current,restored)}catch(_){}}
function saveOrRollback(snapshot,message='Không lưu được thay đổi. Dữ liệu và bản nháp vẫn được giữ lại.'){const saved=Pema.save();if(!saved){restoreState(snapshot);showToast(message);return false}return true}
function appointmentDisplay(x){const date=new Date((x.next||'')+'T12:00:00'),valid=Number.isFinite(date.getTime());return valid?{valid:true,day:date.getDate(),month:date.getMonth()+1,label:date.toLocaleDateString('vi-VN',{weekday:'long',day:'2-digit',month:'2-digit'}),time:x.time||'Chưa chốt giờ'}:{valid:false,day:'—',month:'—',label:'Chưa có lịch hẹn',time:'Liên hệ Pema để đặt lịch'}}
function app(content){const patient=p();document.querySelector('#app').innerHTML=`<div class="mobile-app" data-current-screen="${screen}"><header class="mobile-top"><img class="mobile-logo" src="../shared/assets/pema-logo.png" alt="Pema clinic & spa"><button class="mobile-icon" data-screen="profile" aria-label="Mở hồ sơ demo của ${esc(patient.name)}">${Pema.initials(patient)}</button></header><main class="mobile-content" id="patient-content" tabindex="-1">${content}</main><nav class="mobile-nav">${nav.map(n=>`<button class="${(screen===n[0]||(['progress','care','send'].includes(screen)&&n[0]==='journey')||(screen==='docs'&&n[0]==='profile'))?'active':''}" data-screen="${n[0]}"><span>${icon(n[1])}</span>${n[2]}</button>`).join('')}</nav>${toastTimer?`<div class="mobile-toast" role="status" aria-live="polite">${esc(toastTimer)}</div>`:''}</div>`;bind();PemaUI.enhance(document.querySelector('#app'))}
function home(){const x=p(), ap=appointmentDisplay(x);return `<p class="greeting">Chào ${esc(x.name.split(' ').slice(-1)[0])}</p><h1 class="mobile-heading">Hôm nay của bạn</h1><section class="mobile-card mobile-hero"><div class="hero-symbol">${icon("route")}</div><div class="eyebrow">Hành trình đang tiếp diễn</div><h2>${esc(x.plan)}</h2><p>Buổi ${x.completed} / ${x.total} · Cập nhật ${Pema.date(x.lastVisit)}</p><div class="session-rail" aria-label="${x.completed} trên ${x.total} buổi hoàn tất">${Array.from({length:x.total},(_,i)=>`<span class="${i<x.completed?'complete':''}"></span>`).join('')}</div><button class="btn btn-primary" style="margin-top:14px;font-size:11px" data-screen="journey">Xem hành trình →</button></section><section class="mobile-card home-appointment"><div class="mobile-card-head"><h3>Lịch hẹn tiếp theo</h3><button class="btn btn-quiet" data-screen="appointments">Xem tất cả</button></div><div class="next-appt"><div class="calendar-day"><b>${ap.day}</b><small>Tháng ${String(ap.month).padStart(2,'0')}</small></div><div><h4>Đánh giá mốc tiếp theo</h4><p>${esc(ap.label)} · ${esc(ap.time)}<br>${esc(x.doctor)} · ${esc(x.concern)}</p></div></div></section><section class="mobile-card home-tasks"><div class="mobile-card-head"><h3>Việc hôm nay</h3><span class="chip chip-soft">Pema đồng hành</span></div><div class="quick-actions"><button data-screen="care" aria-label="Xem hướng dẫn"><span>${icon('heart')}</span><strong>Chăm sóc</strong><small>Hướng dẫn tại nhà</small></button><button data-screen="progress"><span>${icon('images')}</span><strong>Ảnh tiến trình</strong><small>So sánh mốc</small></button><button data-screen="send"><span>${icon('message-circle')}</span><strong>Gửi cập nhật</strong><small>Nhắn Pema</small></button></div></section>`}

function appointments(){const x=p(), ap=appointmentDisplay(x);return `<button class="mobile-back" data-screen="home">← Trang chủ</button><h1 class="mobile-page-title">Lịch hẹn</h1><section class="mobile-card"><div class="mobile-card-head"><h3>Sắp tới</h3><span class="chip chip-soft">${ap.valid?"Đã đặt lịch":"Chưa có lịch"}</span></div><div class="next-appt"><div class="calendar-day"><b>${ap.day}</b><small>Tháng ${String(ap.month).padStart(2,'0')}</small></div><div><h4>Đánh giá mốc tiếp theo</h4><p>${esc(ap.label)} · ${esc(ap.time)} · Pema Clinic<br>${esc(x.doctor)} · ${esc(x.concern)}</p></div></div><button class="btn btn-primary" style="width:100%;justify-content:center;margin-top:16px" data-action="confirm-appointment" ${ap.valid?'':'disabled'}>Xác nhận tôi sẽ đến</button></section><section class="mobile-card"><div class="mobile-card-head"><h3>Các lịch đã đặt</h3></div>${PemaOps.seed().appointments.filter(a=>a.patient===x.id&&PemaOps.active(a)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(a=>`<div class="doc-row"><div class="doc-icon">${icon('calendar-days')}</div><div><strong>${Pema.date(a.date)} · ${a.time}</strong><small>${esc(PemaOps.seed().services.find(s=>s.id===a.service).name)} · ${a.duration} phút</small><small>${esc(PemaOps.seed().doctors.find(d=>d.id===a.doctor).name)}</small></div></div>`).join('')||'<p class="subtitle">Chưa có lịch đã đặt.</p>'}</section><section class="mobile-card"><div class="mobile-card-head"><h3>Lịch đã qua</h3></div><div class="doc-row"><div class="doc-icon">✓</div><div><strong>Buổi ${Math.max(1,x.completed)} · ${esc(x.procedure)}</strong><small>${Pema.date(x.lastVisit)} · Đã hoàn tất</small></div><span class="arrow">›</span></div><div class="doc-row"><div class="doc-icon">✓</div><div><strong>Tư vấn ban đầu</strong><small>26/06/2026 · Đã hoàn tất</small></div><span class="arrow">›</span></div></section><div class="notice">Nếu bạn cần đổi lịch, hãy nhắn cho đội ngũ Pema trước ít nhất 4 giờ.</div>`}
function journey(){const x=p();return `<h1 class="mobile-page-title">Hành trình của bạn</h1><section class="mobile-card journey-summary"><div class="eyebrow">Đang điều trị</div><h2>${esc(x.plan)}</h2><div class="mobile-progress"><strong>${x.completed}/${x.total} buổi</strong><div class="progress" role="progressbar" aria-label="Số buổi điều trị đã hoàn tất" aria-valuemin="0" aria-valuemax="${x.total}" aria-valuenow="${x.completed}"><i style="width:${x.completed/x.total*100}%"></i></div></div><p class="progress-caption">Tiến độ số buổi, không phải mức cải thiện da.</p></section><button class="photo-shortcut" data-screen="progress">${icon('images')}<span><strong>Ảnh trước & sau</strong><small>Xem các mốc ảnh trong hành trình</small></span>${icon('chevron-right')}</button><section class="mobile-card journey-events"><div class="mobile-card-head"><h3>Cập nhật gần đây</h3><span class="chip">${x.events.length} mốc</span></div><div class="mobile-timeline">${x.events.slice(0,historyLimit).map(e=>`<details class="event-disclosure"><summary><span class="event-icon">${icon(e.kind==='photo'?'images':e.kind==='followup'?'message-circle':'check')}</span><span><time>${Pema.date(e.date)}</time><strong>${esc(e.title)}</strong></span>${icon('chevron-right')}</summary><p>${esc(e.detail)}</p></details>`).join('')||'<p class="subtitle">Chưa có sự kiện trong hành trình.</p>'}</div>${x.events.length>historyLimit?'<button class="btn btn-quiet history-more" data-action="more-history">Xem thêm lịch sử</button>':''}</section>`}

function progress(){const x=p();return `<button class="mobile-back" data-screen="journey">← Hành trình</button><h1 class="mobile-page-title">Tiến độ số buổi & ảnh</h1><section class="mobile-card"><div class="mobile-card-head"><h3>So sánh mốc ảnh</h3><span class="chip chip-soft">Chính diện</span></div><div class="mobile-photo-row">${Pema.face('before','Trước','pm-a')}${Pema.face('after','Gần nhất','pm-b')}</div><div class="notice">Cùng góc chụp, cùng ánh sáng giúp bác sĩ xem thay đổi trong bối cảnh. Không dùng ảnh này để tự chẩn đoán.</div></section><section class="mobile-card"><div class="mobile-card-head"><h3>Gửi ảnh cập nhật</h3></div><p class="subtitle">Gửi ảnh kèm mô tả để đội ngũ Pema xem và phản hồi.</p><button class="btn btn-primary" data-screen="send">Gửi ảnh cập nhật →</button></section>`}
function care(){const x=p();return `<button class="mobile-back" data-screen="home">← Trang chủ</button><h1 class="mobile-page-title">Chăm sóc tại nhà</h1><section class="mobile-card"><div class="eyebrow">Sau buổi điều trị · ${Pema.date(x.lastVisit)}</div><h2 style="font:700 20px var(--font-ui);color:var(--sage2);margin:7px 0 8px">Mỗi ngày một chút dịu dàng.</h2><p class="subtitle">${esc(x.aftercare)}</p>${x.meds.map(m=>`<div class="care-row" style="margin-top:11px"><div class="care-icon">✦</div><div><h4>${esc(m.name)}</h4><p>${esc(m.use)}</p></div></div>`).join('')}</section><section class="mobile-card"><div class="mobile-card-head"><h3>Khi nào cần nhắn Pema?</h3></div><p style="font-size:11px;color:var(--muted);line-height:1.55;margin:0">Nếu bạn thấy phản ứng bất thường, khó chịu kéo dài hoặc cần hỏi cách chăm sóc, hãy gửi cập nhật trong ứng dụng. Đội ngũ sẽ xem và phản hồi theo quy trình của phòng khám.</p><button class="btn" style="margin-top:14px" data-action="ack-aftercare">${x.aftercareAck?'✓ Đã đọc hướng dẫn':'Tôi đã đọc hướng dẫn'}</button><button class="btn btn-primary" style="margin-top:14px" data-screen="send">Gửi cập nhật →</button></section>`}
function send(){return `<button class="mobile-back" data-screen="care">← Chăm sóc tại nhà</button><h1 class="mobile-page-title">Gửi cập nhật cho Pema</h1><section class="mobile-card"><div class="field"><label for="patient-message">Bạn đang cảm thấy thế nào?</label><textarea id="patient-message" placeholder="Ví dụ: Da hơi khô ở hai má từ tối qua...">${esc(draftMessage)}</textarea></div><div class="upload-box"><div style="font-size:24px">▧</div><p>Thêm ảnh nếu bạn muốn đội ngũ xem vùng da cụ thể.</p><input type="file" accept="image/png,image/jpeg,image/webp" id="patient-photo" aria-label="Ảnh cập nhật cho Pema"><label class="btn" for="patient-photo">Chọn ảnh</label><div id="patient-file" style="font-size:10px;margin-top:7px">${draftPhoto?`Đã chọn: ${esc(draftPhoto.name)} (đã giữ trong phiên demo)`:''}</div>${draftPhoto?`<img id="patient-photo-preview" src="${draftPhoto.data}" alt="Ảnh cập nhật đã chọn — bản demo" aria-label="Xem trước ảnh cập nhật" style="display:block;max-width:180px;max-height:180px;margin-top:10px;border-radius:12px;object-fit:cover">`:''}</div><label class="consent-line" for="patient-consent"><input type="checkbox" id="patient-consent" aria-label="Đồng ý để Pema xem ảnh cập nhật" ${draftConsent?'checked':''}> Tôi đồng ý để đội ngũ Pema xem ảnh này cho mục đích chăm sóc.</label><button class="btn btn-primary" style="width:100%;justify-content:center;margin-top:15px" data-action="send-update">Gửi cho Pema</button><div class="notice">Tin nhắn được gửi tới đội ngũ chăm sóc. Đây không phải kênh cấp cứu.</div></section>`}
function messages(){const x=p();return `<button class="mobile-back" data-screen="home">← Trang chủ</button><h1 class="mobile-page-title">Tin nhắn</h1><section class="mobile-card"><div class="mobile-card-head"><h3>Pema Care Team</h3><span class="status status-green">Đang hỗ trợ</span></div>${x.messages.map(m=>`<div class="message ${m.from==='patient'?'mine':''}">${esc(m.text)}<time>${esc(m.date)}</time></div>`).join('')}<button class="btn btn-primary" style="width:100%;justify-content:center;margin-top:7px" data-screen="send">＋ Gửi tin nhắn</button></section>`}
function docs(){const x=p();return `<button class="mobile-back" data-screen="profile">← Hồ sơ</button><h1 class="mobile-page-title">Tài liệu & hóa đơn</h1><section class="mobile-card"><div class="mobile-card-head"><h3>Hóa đơn của bạn</h3></div>${x.invoices.length?x.invoices.map(i=>`<div class="doc-row"><div class="doc-icon">▤</div><div><strong>${esc(i.label)}</strong><small>${esc(i.id)} · ${esc(i.date)} · ${i.paid?'Đã thanh toán':i.received?'Đã thu một phần · còn '+Pema.money(i.amount-i.received):'Chờ thanh toán'}</small></div><strong style="margin-left:auto;font-size:11px">${Pema.money(i.amount)}</strong></div>`).join(''):'<div class="empty">Chưa có hóa đơn trong demo.</div>'}</section><section class="mobile-card"><div class="mobile-card-head"><h3>Hướng dẫn đã gửi</h3></div><button class="doc-row btn" data-action="open-aftercare"><div class="doc-icon">▧</div><div><strong>Hướng dẫn chăm sóc sau buổi</strong><small>Hướng dẫn đã duyệt · ${Pema.date(x.lastVisit)}</small></div><span class="arrow">›</span></button></section>`}
function profile(){const x=p();return `<h1 class="mobile-page-title">Hồ sơ</h1><section class="mobile-card"><div style="display:flex;gap:13px;align-items:center"><div class="avatar patient-avatar">${Pema.initials(x)}</div><div><h3 style="margin:0 0 4px;font-size:15px">${esc(x.name)}</h3><p style="margin:0;color:var(--muted);font-size:11px">${x.age} tuổi · ${x.phone} · ${x.id}</p></div></div><div class="notice">Bạn đang xem trải nghiệm patient app của hồ sơ demo. Tài khoản và dữ liệu thật sẽ cần xác thực riêng.</div></section><section class="mobile-card"><button class="doc-row btn" data-screen="docs"><div class="doc-icon">▤</div><div><strong>Tài liệu & hóa đơn</strong><small>Xem lịch sử thanh toán và hướng dẫn</small></div><span class="arrow">›</span></button><button class="doc-row btn" data-screen="care"><div class="doc-icon">✦</div><div><strong>Chăm sóc tại nhà</strong><small>Hướng dẫn của kế hoạch hiện tại</small></div><span class="arrow">›</span></button><button class="doc-row btn" data-action="privacy-info"><div class="doc-icon">⚙</div><div><strong>Quyền riêng tư</strong><small>Ảnh chăm sóc: ${x.photoConsent?'đã đồng ý':'chưa đồng ý'}</small></div><span class="arrow">›</span></button></section><section class="mobile-card"><div class="mobile-card-head"><h3>Đổi hồ sơ demo</h3></div><div class="field"><label for="identity-select">Chọn người bệnh tổng hợp</label><select id="identity-select">${Pema.state.patients.slice(0,8).map(q=>`<option value="${q.id}" ${q.id===identity?'selected':''}>${esc(q.name)} · ${q.id}</option>`).join('')}</select></div><p style="font-size:10px;color:var(--muted);margin:0">Chỉ dùng để trình diễn trải nghiệm liên thông; không đại diện đăng nhập thật.</p></section>`}
function render(){Pema.reload();let c=screen==='home'?home():screen==='appointments'?appointments():screen==='journey'?journey():screen==='progress'?progress():screen==='care'?care():screen==='send'?send():screen==='messages'?messages():screen==='docs'?docs():profile();app(c)}
function showToast(msg){toastTimer=msg;render();clearTimeout(window.__toast);window.__toast=setTimeout(()=>{toastTimer='';render()},2800)}
function bind(){document.querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>{screen=b.dataset.screen;historyLimit=3;render();document.querySelector('.mobile-content').scrollTop=0});const sel=$('#identity-select');if(sel)sel.onchange=()=>{identity=Pema.state.patients.some(q=>q.id===sel.value)?sel.value:'P001';draftMessage='';draftPhoto=null;draftConsent=false;try{localStorage.setItem('pema-patient-identity',identity)}catch(_){}render();showToast('Đã đổi hồ sơ demo')};const pf=$('#progress-photo');if(pf)pf.onchange=()=>{$('#progress-file').textContent=pf.files[0]?pf.files[0].name:''};const pt=$('#patient-photo');if(pt){pt.onchange=async()=>{const file=pt.files[0];draftConsent=false;const consentBox=$('#patient-consent');if(consentBox)consentBox.checked=false;if(!file){draftPhoto=null;render();return}try{const data=await Pema.imageData(file);draftPhoto={name:file.name,data};const label=$('#patient-file');if(label)label.textContent=`Đã chọn: ${file.name} (đã giữ trong phiên demo)`;let preview=$('#patient-photo-preview');if(!preview){preview=document.createElement('img');preview.id='patient-photo-preview';preview.alt='Ảnh cập nhật đã chọn — bản demo';preview.setAttribute('aria-label','Xem trước ảnh cập nhật');preview.style.cssText='display:block;max-width:180px;max-height:180px;margin-top:10px;border-radius:12px;object-fit:cover';pt.parentElement.appendChild(preview)}preview.src=data}catch(e){draftPhoto=null;showToast(e.message)}};const msg=$('#patient-message');if(msg){msg.oninput=()=>{draftMessage=msg.value}}const consent=$('#patient-consent');if(consent)consent.onchange=()=>{draftConsent=consent.checked}}document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));}
async function action(a){const x=p();if(a==='more-history'){historyLimit+=3;render();return}if(a==='open-aftercare'){screen='care';render();return}if(a==='ack-aftercare'){const snapshot=stateSnapshot();x.aftercareAck=true;Pema.addEvent(x,'aftercare','Người bệnh đã đọc hướng dẫn chăm sóc','Xác nhận từ patient app.','Patient app');if(!saveOrRollback(snapshot))return;showToast('Đã ghi nhận bạn đã đọc hướng dẫn');return}if(a==='privacy-info'){const snapshot=stateSnapshot();x.photoConsent=!x.photoConsent;Pema.log(x.photoConsent?'Đồng ý sử dụng ảnh chăm sóc':'Rút đồng ý ảnh chăm sóc',x.id);if(!saveOrRollback(snapshot))return;showToast(x.photoConsent?'Đã đồng ý ảnh cho chăm sóc trong demo':'Đã tắt đồng ý ảnh chăm sóc trong demo');return}if(a==='confirm-appointment'){if(!appointmentDisplay(x).valid){showToast('Chưa có lịch hẹn để xác nhận');return}const snapshot=stateSnapshot();x.messages.push({from:'clinic',text:`Lịch hẹn ngày ${Pema.date(x.next)} lúc ${x.time||'10:30'} đã được xác nhận. Hẹn gặp bạn tại Pema.`,date:'20/09 · vừa xong'});Pema.addEvent(x,'appointment','Người bệnh đã xác nhận lịch hẹn','Xác nhận từ patient app.','Pema Care Team');if(!saveOrRollback(snapshot))return;showToast('Đã xác nhận lịch hẹn');return}if(a==='send-update'){const text=$('#patient-message').value.trim();draftMessage=$('#patient-message').value;if(!text){showToast('Hãy viết vài dòng cập nhật');return}const consent=$('#patient-consent');if((draftPhoto||$('#patient-photo')?.files[0])&&consent&&!consent.checked){showToast('Bạn cần đồng ý để Pema xem ảnh cập nhật');return}const file=$('#patient-photo')?.files[0];let imageData=draftPhoto?.data||null;try{if(file){imageData=await Pema.imageData(file);draftPhoto={name:file.name,data:imageData}}}catch(e){showToast(e.message);return}Pema.reload();const current=Pema.patient(identity);const snapshot=stateSnapshot();current.messages.push({from:'patient',text,date:'20/09 · vừa xong'});const f={id:'F'+Date.now(),patient:current.id,type:imageData?'Ảnh cần bác sĩ xem':'Phản hồi từ patient app',priority:'review',symptom:text,date:new Date().toISOString(),image:imageData?'placeholder':null,imageData,status:'open',owner:'BS. Tâm'};Pema.state.followups.unshift(f);Pema.addEvent(current,'followup','Đã gửi cập nhật cho Pema',text,'Patient app');if(!saveOrRollback(snapshot))return;draftMessage='';draftPhoto=null;draftConsent=false;screen='messages';showToast('Đã gửi cập nhật tới đội ngũ Pema');return}}
window.addEventListener('pema-external',()=>{if(screen!=='send'&&screen!=='progress')render()});window.addEventListener('pema-change',()=>{if(!toastTimer&&screen!=='send'&&screen!=='progress')render()});render();
})();

